-- Expected results are generated by the actual TypeScript lab functions.
local ns=...
local M=ns.ConceptModel
local fixtures=assert(loadfile('tests/concept-fixtures.lua'))()
local comparisons=0
local function Same(actual,expected,path)
	path=path or 'fixture'; comparisons=comparisons+1
	if type(expected)=='table' then
		assert(type(actual)=='table',path..': expected table, got '..tostring(actual))
		for key,value in pairs(expected) do Same(actual[key],value,path..'.'..tostring(key)) end
		if #expected>0 then assert(#actual==#expected,path..': array length differs') end
	else assert(actual==expected,path..': '..tostring(actual)..' ~= '..tostring(expected)) end
end
local items={}
for i,fixture in ipairs(fixtures.results) do
	local item=fixture.item
	if item.name and item.units>0 then items[#items+1]=item end
	for _,order in ipairs(fixture.orders) do Same(M:Order(item,order.wanted),order.result,'orders.'..i) end
	Same(M:Confidence(item),fixture.confidence,'confidence.'..i)
	for _,deal in ipairs(fixture.deals) do Same(M:Deal(item,deal.units,deal.cost),deal.result,'deal.'..i) end
	for _,rule in ipairs(ns.Concept.priceRules) do Same(M:Price(item,rule.id),fixture.prices[rule.id],'price.'..i..'.'..rule.id) end
	for _,plan in ipairs(fixture.resells) do Same(M:Resell(item,plan.margin,plan.budget,plan.limit),plan.result,'resell.'..i) end
end
for i,fixture in ipairs(fixtures.matches) do
	local keys={}; for _,item in ipairs(items) do if M:Matches(item,fixture.selection) then keys[#keys+1]=item.key end end
	Same(keys,fixture.keys,'facets.'..i)
end
for _,fixture in ipairs(fixtures.options) do
	for _,category in ipairs(ns.Concept.categories) do if category.id==fixture.id then Same(M:Options(category,items),fixture.result,'options.'..fixture.id) end end
end
for i,fixture in ipairs(fixtures.filtered) do
	local keys={}; for _,item in ipairs(items) do if M:Filter(item,fixture.filter,500) then keys[#keys+1]=item.key end end
	Same(keys,fixture.keys,'filters.'..i)
end
print('Concept parity passed: '..comparisons..' comparisons against lab-generated results.')
